const std = @import("std");
const builtin = @import("builtin");

pub const vkCallconv: std.builtin.CallingConvention = if (builtin.os.tag == .windows and builtin.cpu.arch == .x86)
    .Stdcall
else if (builtin.abi == .android and (builtin.cpu.arch.isARM() or builtin.cpu.arch.isThumb()) and std.Target.arm.featureSetHas(builtin.cpu.features, .has_v7) and builtin.cpu.arch.ptrBitWidth() == 32)
    .AAPCSVFP
else
    .C;

pub var gInstance: Instance = null;
pub var gDevice: Device = null;

pub fn toFlags(bits: anytype) Flags {
    var result: Flags = 0;

    for (bits) |bit| {
        result |= @intCast(@intFromEnum(bit));
    }

    return result;
}
