pub fn makeVideoStdVersion(major: u32, minor: u32, patch: u32) u32 {
    return (major << 22) | (minor << 12) | patch;
}

pub const codecH264DecodeApiVersion100 = makeVideoStdVersion(1, 0, 0);
pub const codecH264EncodeApiVersion100 = makeVideoStdVersion(1, 0, 0);
pub const codecH265DecodeApiVersion100 = makeVideoStdVersion(1, 0, 0);
pub const codecH265EncodeApiVersion100 = makeVideoStdVersion(1, 0, 0);
pub const codecVp9DecodeApiVersion100 = makeVideoStdVersion(1, 0, 0);
pub const codecAv1DecodeApiVersion100 = makeVideoStdVersion(1, 0, 0);
pub const codecAv1EncodeApiVersion100 = makeVideoStdVersion(1, 0, 0);
